SELECT curr.PROJECT_ID as projectId, curr.PROJECT_NAME as projectName, parent.PROJECT_ID as parentProjectId, parent.PROJECT_NAME as parentProjectName,
CASE WHEN curr.PARENT_PROJECT_ID IS NULL THEN curr.PROJECT_NAME ELSE parent.PROJECT_NAME END as displayProjectName,
CASE WHEN curr.PARENT_PROJECT_ID IS NULL THEN NULL ELSE curr.PROJECT_NAME END as displaySubProjectName FROM projects curr LEFT JOIN projects parent ON curr.PARENT_PROJECT_ID = parent.PROJECT_ID WHERE curr.PROJECT_ID = #{projectId}
